# Break My Fix finding 4, generated by Tracefix: Env.db_url_config returns a wrong value.
# Property (docstring): Every key/value in a non-empty extra_options dict appears in result['OPTIONS'], overriding query-string values
# Quote: Values in ``extra_options`` override query-string ``OPTIONS``.
# Run it with pytest: it fails for as long as the code breaks this property.

from environ.environ import Env


def test_break_my_fix_4() -> None:
    url = 'sqlite://:memory:'
    extra_options = {'timeout': 20}
    # The property applies to this input: isinstance(extra_options, dict) and len(extra_options) > 0 and isinstance(url, str) and url.split('://')[0] in Env.DB_SCHEMES
    result = Env.db_url_config(url=url, extra_options={'timeout': 20})
    assert ('OPTIONS' in result and all(k in result['OPTIONS'] and result['OPTIONS'][k] == v for k, v in extra_options.items()))
